/**
 * 跨 Shadow DOM 的元素查询 + 应用视口尺寸。
 *
 * 背景：Readest 作为 embed 被挂进宿主的 Shadow DOM 后，shadow tree 里的元素
 * 对 `document.querySelector` 是**不可见**的 —— 文档查询只在 light DOM 里找。
 * 于是所有「用 document 找自己影子树里的节点」的代码都会拿到 null：
 *
 *   - Annotator.tsx / annotatorUtil.ts / FootnotePopup.tsx
 *     `document.querySelector('#gridcell-' + bookKey)` → 拿不到阅读区格子
 *       → 选中文字后的浮动工具条（复制/高亮/注释/搜索/词典/翻译/朗读/校对）
 *         无法定位，工具条不出现。
 *   - useAutoPageTurn.ts 的 `#gridcell-` 查询同理失效。
 *   - themeStore 的 `document.querySelector('[data-readest-embed-root]')` 拿不到
 *     embed 容器 → data-theme 被写到宿主 documentElement 上，污染宿主主题。
 *
 * 这里统一提供「从当前应用根节点（= embed 根容器或 document）向下查」的查询函数：
 * 在 Next.js 独立运行时，应用根就是 document，行为与原来完全一致；
 * 在 embed 里，应用根是 shadow 内的容器，查询能穿透到 shadow tree 内部。
 */

/**
 * embed 场景下由 mountReadest 注入的应用根元素；独立运行时不设置（= document）。
 *
 * SSR 安全：不能写成 `let appRoot = document` —— 模块顶层会在导入时立即求值，
 * 而静态导出（output: export）的「Collecting page data」阶段会在 Node 里
 * 加载这个模块，此时没有 document，直接抛 `ReferenceError: document is not defined`
 * 并中断整个导出。所以这里存 null，用 getAppRoot() 时再惰性回退到 document。
 */
let appRoot: Document | HTMLElement | null = null;

/** 独立运行时的应用根就是 document；SSR 下没有 document，返回 null。 */
const getDefaultAppRoot = (): Document | HTMLElement | null =>
  typeof document !== 'undefined' ? document : null;

/** 供 embed 入口调用：把应用根设为 shadow 内的容器元素。 */
export const setAppRoot = (root: Document | HTMLElement) => {
  appRoot = root;
};

/**
 * 当前应用根（embed 下是 shadow 内的容器元素，独立运行是 document）。
 * SSR 预渲染阶段返回 null —— 此时没有任何 DOM 可查，调用方需能容忍。
 */
export const getAppRoot = (): Document | HTMLElement | null =>
  appRoot ?? getDefaultAppRoot();


/**
 * 在应用根内查询单个元素。
 * 注意：querySelector 只匹配**后代**，不匹配根元素自身 —— 而 embed 的应用根
 * （styleHost）自己就带 [data-readest-embed-root] 属性，主题写入等调用查的正是
 * 根本身，所以这里先对根做 matches 自检，否则永远返回 null → 主题被误写到宿主
 * <html> 上（书库/阅读界面 scoped 主题因此全部失效）。
 * 找不到时再退回 document（兼容极少数把节点渲染到 light DOM 的场景）。
 */
export const queryApp = <T extends Element = HTMLElement>(
  selector: string,
): T | null => {
  const root = getAppRoot();
  // SSR 预渲染阶段没有任何 DOM，直接返回 null
  if (!root) return null;
  if (root instanceof Element && root.matches(selector)) {
    return root as T;
  }
  const found = root.querySelector<T>(selector);
  if (found) return found;
  if (root !== document) return document.querySelector<T>(selector);
  return null;
};

/** 在应用根内查询全部匹配元素。 */
export const queryAllApp = <T extends Element = HTMLElement>(
  selector: string,
): T[] => {
  const results: T[] = [];
  const root = getAppRoot();
  // SSR 预渲染阶段没有任何 DOM，返回空数组
  if (!root) return results;
  if (root instanceof Element && root.matches(selector)) {
    results.push(root as T);
  }
  results.push(...Array.from(root.querySelectorAll<T>(selector)));
  if (results.length > 0) return results;
  if (root !== document) {
    return Array.from(document.querySelectorAll<T>(selector));
  }
  return [];
};

/**
 * 主题（data-theme / color-scheme 等继承型 CSS 变量）应写入的宿主元素：
 * embed 下是 shadow 内的容器（变量随之继承进整棵 shadow 树），
 * 独立运行时是 documentElement，与原行为一致。
 */
export const getThemeHost = (): HTMLElement | null => {
  const root = getAppRoot();
  if (root instanceof HTMLElement) return root;
  return typeof document !== 'undefined' ? document.documentElement : null;
};


/**
 * 应用视口尺寸。
 *
 * embed 模式下，Readest 只占宿主页面内容区的一小块 —— 浮动控件（ReaderDial 转盘、
 * 弹层、菜单）如果按 window.innerWidth/innerHeight 算位置，会跑到宿主侧栏或
 * 视口边缘外面去（转盘曾因此被真题站左侧栏完全遮住）。
 * 由于 embed 根容器带 transform，它是内部 position:fixed 元素的包含块，
 * 因此 fixed 坐标系的原点就是该容器，尺寸也应当用容器尺寸而非 window。
 */
export const getAppViewport = (): { width: number; height: number } => {
  const root = getAppRoot();
  if (root instanceof HTMLElement) {
    return { width: root.clientWidth, height: root.clientHeight };
  }
  // SSR 预渲染阶段没有视口，返回 0 让调用方走降级分支
  if (typeof window === 'undefined') return { width: 0, height: 0 };
  return { width: window.innerWidth, height: window.innerHeight };
};
